// src/data/curated-verticals.ts
function normUrl(url) {
  return url.replace(/\/$/, "").replace(/^http:/, "https:");
}
function hostnameOf(url) {
  try {
    return new URL(normUrl(url)).hostname.replace(/^www\./, "");
  } catch {
    return normUrl(url);
  }
}
var PRIMARY_ORDER = [
  "beauty",
  "apparel",
  "home",
  "food",
  "wellness",
  "pet",
  "accessories",
  "fun",
  "outdoor",
  "kids"
];
var byHost = /* @__PURE__ */ new Map();
var byUrl = /* @__PURE__ */ new Map();
for (const key of PRIMARY_ORDER) {
  const list = curated_dtc_default.verticals[key] ?? [];
  for (const u of list) {
    const n = normUrl(u);
    if (!byUrl.has(n)) byUrl.set(n, key);
    const h = hostnameOf(u);
    if (!byHost.has(h)) byHost.set(h, key);
  }
}
for (const [vertical, urls] of Object.entries(curated_dtc_default.verticals)) {
  if (PRIMARY_ORDER.includes(vertical)) continue;
  for (const u of urls) {
    const n = normUrl(u);
    if (!byUrl.has(n)) byUrl.set(n, vertical);
    const h = hostnameOf(u);
    if (!byHost.has(h)) byHost.set(h, vertical);
  }
}
function verticalForUrl(url) {
  const n = normUrl(url);
  return byUrl.get(n) ?? byHost.get(hostnameOf(url)) ?? "unknown";
}
function listCuratedVerticals() {
  const counts = /* @__PURE__ */ new Map();
  for (const v of byHost.values()) counts.set(v, (counts.get(v) ?? 0) + 1);
  return [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).map(([v]) => v);
}

